6	// Verification: AllocationTests (incl. concurrent allocations), SeededLicense*Tests
7	// Confidence: High
8	
9	using System.Security.Cryptography;
10	using Microsoft.EntityFrameworkCore;
11	using ResourceHub.Api.Contracts;
12	using ResourceHub.Api.Data;
13	using ResourceHub.Api.Domain;
14	
15	namespace ResourceHub.Api.Services;
16	
17	/// <summary>
18	/// Runs POST /api/v1/assets/tickets/{id}/allocate (requirement 4, spec 6.9 and 6.10).
19	/// The ticket row and the requested asset rows are locked (in asset id order, so two
20	/// allocations cannot deadlock) for one transaction. Stock is checked for every item
21	/// before anything changes; if any item is short, nothing is written except a failure event.
22	/// </summary>
23	public sealed class AllocationService(HubDbContext db, TimeProvider clock, ILogger<AllocationService> log)
24	{
25	    public async Task<IResult> AllocateAsync(Guid ticketId, Actor actor, CancellationToken ct)
26	    {
27	        var now = clock.GetUtcNow();
28	        await using var tx = await db.Database.BeginTransactionAsync(ct);
29	
30	        var ticket = await db.Tickets
31	            .FromSql($"SELECT * FROM tickets WHERE \"Id\" = {ticketId} FOR UPDATE")
32	            .FirstOrDefaultAsync(ct);
33	        if (ticket is null)
34	        {
35	            return Problems.NotFound("Ticket not found.");
36	        }
37	
38	        if (ticket.Status != TicketStatus.Approved)
39	        {
40	            var status = ticket.Status.ToString().ToLowerInvariant();
41	            await RecordFailureAsync(tx, ticket, actor, now, $"Ticket is {status}, not approved.", ct);
42	            return Problems.Conflict("Only approved tickets can be allocated.", $"The ticket is {status}.");
43	        }
44	
45	        var items = await db.TicketItems.AsNoTracking().Where(i => i.TicketId == ticketId).ToListAsync(ct);
46	        var assetIds = items.Select(i => i.AssetId).Distinct().OrderBy(id => id).ToArray();
47	        var assets = await db.Assets
48	            .FromSql($"SELECT * FROM assets WHERE \"Id\" = ANY({assetIds}) ORDER BY \"Id\" FOR UPDATE")
49	            .ToDictionaryAsync(a => a.Id, ct);
50	
51	        var shortages = FindShortages(items, assets);
52	        if (shortages.Count > 0)
53	        {
54	            var detail = string.Join("; ", shortages.Select(s => $"{s.AssetName}: requested {s.Requested}, available {s.Available}"));
55	            await RecordFailureAsync(tx, ticket, actor, now, "Not enough stock. " + detail, ct);
56	            log.LogWarning("Allocation of ticket {TicketId} failed for lack of stock on {ShortCount} asset(s)", ticketId, shortages.Count);
57	            return Problems.Conflict(
58	                "Not enough stock to allocate this ticket.",
59	                "Nothing was allocated; the ticket stays approved and allocation can be run again later.",
60	                new Dictionary<string, object?> { ["shortages"] = shortages });
61	        }
62	
63	        var results = new List<AllocationDto>();
64	        foreach (var item in items.OrderBy(i => assets[i.AssetId].Name).ThenBy(i => i.AssetId))
65	        {
66	            var asset = assets[item.AssetId];
67	            var allocation = new Allocation
68	            {
69	                Id = Guid.NewGuid(),
70	                TicketId = ticketId,
71	                AssetId = asset.Id,
72	                AssetType = asset.Type,
73	                Quantity = item.Quantity,
74	                Amount = item.Amount,
75	                AllocatedAt = now,
76	            };
77	            db.Allocations.Add(allocation);
78	
79	            List<string>? keys = null;
80	            List<DeviceDto>? devices = null;
81	            switch (asset.Type)
82	            {
83	                case AssetType.Physical:
84	                {
85	                    var qty = item.Quantity!.Value;
86	                    asset.RemainingUnits -= qty;
87	                    var due = now.AddDays(item.LoanDays ?? asset.DefaultLoanDays!.Value);
88	                    devices = [];
89	                    for (var n = 0; n < qty; n++)
90	                    {
91	                        var token = NewToken();
92	                        db.DeviceAssignments.Add(new DeviceAssignment
93	                        {
94	                            Id = Guid.NewGuid(), Token = token, AllocationId = allocation.Id, AssetId = asset.Id,
95	                            TicketId = ticketId, CheckedOutAt = now, DueAt = due,
96	                        });
97	                        devices.Add(new DeviceDto(token, now, due, null, "checkedout"));
98	                    }
99	                    break;
100	                }
101	                case AssetType.License:
102	                {
103	                    var qty = item.Quantity!.Value;
104	                    var free = await db.LicenseKeys
105	                        .Where(k => k.AssetId == asset.Id && k.IssuedTicketId == null)
106	                        .OrderBy(k => k.Id)
107	                        .Take(qty)
108	                        .ToListAsync(ct);
109	                    foreach (var key in free)
110	                    {
111	                        key.IssuedTicketId = ticketId;
112	                        key.AllocationId = allocation.Id;
113	                        key.IssuedAt = now;
114	                    }
115	                    asset.RemainingUnits -= qty;
116	                    keys = free.Select(k => k.Key).ToList();
117	                    break;
118	                }
119	                case AssetType.Voucher:
120	                    asset.Balance -= item.Amount!.Value;
121	                    break;
122	            }
123	            asset.UpdatedAt = now;
124	
125	            results.Add(new AllocationDto(
126	                allocation.Id, ticketId, asset.Id, asset.Name, asset.Type, asset.Category, now,
127	                allocation.Quantity, allocation.Amount, keys, devices));
128	        }
129	
130	        ticket.Status = TicketStatus.Allocated;
131	        ticket.AllocatedAt = now;
132	        ticket.UpdatedAt = now;
133	        db.TicketEvents.Add(TicketEvents.Create(ticketId, TicketEventType.AllocationSucceeded,
134	            TicketStatus.Approved, TicketStatus.Allocated, actor.Id, now, $"{results.Count} asset(s) allocated"));
135	
136	        await db.SaveChangesAsync(ct);
137	        await tx.CommitAsync(ct);
138	        log.LogInformation("Ticket {TicketId} allocated by {ActorId}: {AssetCount} asset(s), {DeviceCount} device(s), {KeyCount} key(s), {Credits} credits",
139	            ticketId, actor.Id, results.Count,
140	            results.Sum(r => r.Devices?.Count ?? 0), results.Sum(r => r.LicenseKeys?.Count ?? 0), results.Sum(r => r.Amount ?? 0m));
141	
142	        return Results.Ok(new AllocationResultDto(ticketId, TicketStatus.Allocated, now, results));
143	    }
144	
145	    private static List<ShortageDto> FindShortages(List<TicketItem> items, Dictionary<Guid, Asset> assets)
146	    {
147	        var shortages = new List<ShortageDto>();
148	        foreach (var item in items)
149	        {
150	            var asset = assets[item.AssetId];
151	            var (requested, available) = asset.Type == AssetType.Voucher
152	                ? (item.Amount ?? 0m, asset.Balance ?? 0m)
153	                : (item.Quantity ?? 0, (decimal)(asset.RemainingUnits ?? 0));
154	            if (requested > available)
155	            {
156	                shortages.Add(new ShortageDto(asset.Id, asset.Name, requested, available));
157	            }
158	        }
159	        return shortages;
160	    }
161	
162	    /// <summary>Rolls back anything pending, then logs the failed attempt (spec 6.13).</summary>
163	    private async Task RecordFailureAsync(
164	        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx, Ticket ticket, Actor actor, DateTimeOffset now, string detail, CancellationToken ct)
165	    {
166	        await tx.RollbackAsync(ct);
167	        db.ChangeTracker.Clear();
168	        db.TicketEvents.Add(TicketEvents.Create(ticket.Id, TicketEventType.AllocationFailed, ticket.Status, ticket.Status, actor.Id, now, detail));
169	        await db.SaveChangesAsync(ct);
170	    }
171	
172	    /// <summary>Hardware assignment token: unguessable, so it can identify a device at return.</summary>
173	    private static string NewToken() => "HW-" + Convert.ToHexString(RandomNumberGenerator.GetBytes(10));
174	}
